import { test, expect, type APIRequestContext } from '@playwright/test';

const PNG_32X32 = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAKklEQVR4nGP4Yh9HU8QwasGoBaMWjFowasGoBaMWjFowasGoBaMWDBULAN4gRFtH0KHXAAAAAElFTkSuQmCC',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function loginUser(
  request: APIRequestContext,
  email: string,
  nickname: string
): Promise<{ id: string; email: string; nickname: string }> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status()).toBe(200);
  const sendJson = await sendRes.json();
  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode, nickname },
  });
  expect(verifyRes.status()).toBe(200);
  return (await verifyRes.json()).user;
}

test.describe.serial('通知、导航栏改版、左右详情与 WebSocket 草案测试', () => {
  test('1. 通知基础流程与左侧导航展示', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    try {
      const userA = await loginUser(page.request, makeEmail('draft-a'), '作者甲');
      await loginUser(ctxB.request, makeEmail('draft-b'), '访客乙');

      const postRes = await page.request.post('/api/posts', {
        data: { title: `草案帖-${Date.now()}`, content: '正文测试' },
      });
      const postId = (await postRes.json()).post.id;

      await ctxB.request.post(`/api/users/${userA.id}/follow`);
      await ctxB.request.post(`/api/posts/${postId}/like`);
      await ctxB.request.post(`/api/posts/${postId}/comments`, { data: { content: '很棒的分享' } });

      await page.goto('/');
      const sidebar = page.locator('aside, nav').first();
      const notifNav = sidebar
        .getByRole('button', { name: /通知/ })
        .or(sidebar.getByRole('link', { name: /通知/ }))
        .first();
      await expect(notifNav).toBeVisible();
      await notifNav.click();
      await expect(page.getByText('很棒的分享').first()).toBeVisible();
    } finally {
      await ctxB.close();
    }
  });

  test('2. 动态详情左右结构与图片评论展示', async ({ page }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    await loginUser(page.request, makeEmail('draft-detail'), '摄影师');
    const upload = await page.request.post('/api/uploads', {
      multipart: { file: { name: 'p.png', mimeType: 'image/png', buffer: PNG_32X32 } },
    });
    const { url } = await upload.json();
    const title = `双栏测试-${Date.now()}`;
    await page.request.post('/api/posts', {
      data: { title, content: '图文测试内容', imageUrl: url },
    });
    await page.goto('/');
    await page.getByText(title).first().click();
    const dialog = page.getByRole('dialog').first();
    await expect(dialog).toBeVisible();
    await expect(dialog.getByText(title).first()).toBeVisible();
  });
});
